package bookstore

import "sort"

// groupCosts[k] is the total cost of a group of k distinct books.
// One book costs $8 (800 cents); groups of 2, 3, 4 and 5 distinct
// books get 5%, 10%, 20% and 25% discounts respectively.
var groupCosts = []int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket.
// Basket entries are book titles numbered 1 through 5.
func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}
	return minCost(counts, map[[5]int]int{})
}

// minCost finds the cheapest way to group the books described by counts,
// where counts[i] is the number of copies of title i.
//
// It is never worse to form a group from the titles with the most copies
// remaining, so we only consider taking one book from each of the k most
// plentiful titles, for every possible group size k. The result is memoized
// per count vector.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if cost, ok := memo[counts]; ok {
		return cost
	}

	// Sort counts in descending order so the most plentiful titles come first.
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	k := 0
	for i := 0; i < 5; i++ {
		if counts[i] > 0 {
			k++
		} else {
			break
		}
	}
	if k == 0 {
		return 0
	}

	best := -1
	for size := 1; size <= k; size++ {
		next := counts
		for i := 0; i < size; i++ {
			next[i]--
		}
		cost := groupCosts[size] + minCost(next, memo)
		if best == -1 || cost < best {
			best = cost
		}
	}

	memo[counts] = best
	return best
}

